  }),
  async (c) => {
    const userId = c.get("userId") as string
    const { limit, startDate, endDate } = parseRecapWindow(c)
    const repoParam = c.req.query("repo")?.trim() || null

    try {
      const db = getDb(c.env)
      const user = await db.users.getWithCache(c.env.ENTIRE_CACHE, userId)
      if (!user) return c.json({ error: "User not found" }, 404)

      // Pull both sides from the same source (repo_checkpoints) with disjoint
      // author filters: me = user's github_id, team = everyone else on repos
      // the user has commit activity in. Cross-repo by default; repoParam
      // narrows both sides to the same repo when provided.
      const since = startDate.toISOString()
      const until = endDate.toISOString()
      const [myCheckpointsAll, teamCheckpointsAll] = await Promise.all([
        db.checkpoints.getByUser(userId, user.github_id, since, until, limit),
        db.checkpoints.getTeamOnUserRepos(userId, user.github_id, since, until, limit),
      ])

      const myCheckpoints = repoParam
        ? myCheckpointsAll.filter((cp) => cp.repo_full_name === repoParam)
        : myCheckpointsAll
      const teamCheckpoints = repoParam
        ? teamCheckpointsAll.filter((cp) => cp.repo_full_name === repoParam)
        : teamCheckpointsAll

      // Base per-agent counts + tokens come straight off the checkpoint
      // rows (input_tokens + output_tokens). No custom aggregator needed.
      const meByAgent = aggregateCheckpointsByAgent(myCheckpoints)
      const teamByAgent = aggregateCheckpointsByAgent(teamCheckpoints)

      // Merge analysis-derived fields (labels, skills, mcpServers, toolMix,
      // transcriptTokens, filesChanged) for both sides. Analyses live on
      // repo_checkpoint_analyses keyed by (repo_id, checkpoint_id).
      await mergeAnalysesInto(db, meByAgent, myCheckpoints)
      await mergeAnalysesInto(db, teamByAgent, teamCheckpoints)

      // Daily activity from the user's own checkpoints — powers the CLI
      // activity strip. Computed here so CLI doesn't need a second call.
      const daily = buildDailyActivity(myCheckpoints, startDate, endDate)

      // Summary across both sides (used by the CLI's context line).
      const distinctOthers = new Set(
        teamCheckpoints.map((cp) => cp.commit_sha ?? "").filter((s) => s !== ""),
      )
      const contribSummary = {
        distinctUsers: distinctOthers.size > 0 ? distinctOthers.size + 1 : 1,
        totalTokens: sumTokens(myCheckpoints) + sumTokens(teamCheckpoints),
        totalCheckpoints: myCheckpoints.length + teamCheckpoints.length,
      }

      // Assemble final per-agent map. Agents that appear on either side.
      const allAgents = new Set<string>([...Object.keys(meByAgent), ...Object.keys(teamByAgent)])
      const agents: Record<string, { me: AgentAggregate; contributors: AgentAggregate | null }> = {}
      for (const name of allAgents) {
        agents[name] = {
          me: meByAgent[name] ?? emptyAggregate(),
          contributors: teamByAgent[name] ?? null,
        }
      }

      return c.json({
        timeframe: c.req.query("timeframe") ?? "last-6-months",
        repo: repoParam,
        since,
        until,
        agents,
        contributors: contribSummary,
        daily,
        updated_at: new Date().toISOString(),
      })
    } catch (err) {
      console.error("Failed to build recap:", err)
      recordSpanError(err)
      return c.json({ error: "Failed to build recap" }, 500)
    }
  },
)

// parseRecapWindow accepts either explicit `since`/`until` ISO8601 params
// or falls back to the timeframe enum (last-month / last-3-months /
// last-6-months). Explicit dates give the CLI precise control so its
// --day / --week / --month ranges line up exactly with the server's
// aggregation boundaries.
function parseRecapWindow(c: Context<{ Bindings: Env; Variables: Variables }>) {
  const sinceParam = c.req.query("since")
  const untilParam = c.req.query("until")
  if (sinceParam && untilParam) {
    const startDate = new Date(sinceParam)
    const endDate = new Date(untilParam)
    const limitParam = c.req.query("limit")
    const parsedLimit = limitParam ? parseInt(limitParam, 10) : 500
    const limit = Number.isNaN(parsedLimit) || parsedLimit <= 0 ? 500 : Math.min(parsedLimit, 1000)
    if (!Number.isNaN(startDate.getTime()) && !Number.isNaN(endDate.getTime())) {
      return { limit, startDate, endDate }
    }
  }
  return parseTimeframeParams(c)
